CREATE TABLE IF NOT EXISTS exchanges(id BIGSERIAL PRIMARY KEY, code VARCHAR(10) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS sectors(id BIGSERIAL PRIMARY KEY, name VARCHAR(120) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS stocks(id BIGSERIAL PRIMARY KEY, symbol VARCHAR(30) NOT NULL, company_name VARCHAR(255), exchange_id BIGINT REFERENCES exchanges(id), sector_id BIGINT REFERENCES sectors(id), UNIQUE(symbol,exchange_id));
CREATE TABLE IF NOT EXISTS historical_prices(id BIGSERIAL PRIMARY KEY, stock_id BIGINT REFERENCES stocks(id), ts TIMESTAMPTZ NOT NULL, open NUMERIC, high NUMERIC, low NUMERIC, close NUMERIC, volume BIGINT, UNIQUE(stock_id,ts));
CREATE TABLE IF NOT EXISTS news(id BIGSERIAL PRIMARY KEY, stock_id BIGINT REFERENCES stocks(id), headline TEXT, url TEXT, source VARCHAR(120), published_at TIMESTAMPTZ, sentiment NUMERIC);
CREATE TABLE IF NOT EXISTS sentiment_scores(id BIGSERIAL PRIMARY KEY, stock_id BIGINT REFERENCES stocks(id), ts TIMESTAMPTZ, source VARCHAR(50), score NUMERIC);
CREATE TABLE IF NOT EXISTS technical_indicators(id BIGSERIAL PRIMARY KEY, stock_id BIGINT REFERENCES stocks(id), ts TIMESTAMPTZ, values JSONB);
CREATE TABLE IF NOT EXISTS predictions(id BIGSERIAL PRIMARY KEY, stock_id BIGINT REFERENCES stocks(id), created_at TIMESTAMPTZ DEFAULT NOW(), horizon VARCHAR(30), signal VARCHAR(30), confidence NUMERIC, expected_return NUMERIC, risk VARCHAR(20), model_version VARCHAR(60));
CREATE TABLE IF NOT EXISTS portfolios(id BIGSERIAL PRIMARY KEY, user_ref VARCHAR(120), name VARCHAR(120));
CREATE TABLE IF NOT EXISTS portfolio_positions(id BIGSERIAL PRIMARY KEY, portfolio_id BIGINT REFERENCES portfolios(id), stock_id BIGINT REFERENCES stocks(id), quantity NUMERIC, average_price NUMERIC);
CREATE TABLE IF NOT EXISTS alerts(id BIGSERIAL PRIMARY KEY, user_ref VARCHAR(120), stock_id BIGINT REFERENCES stocks(id), rule JSONB, channel VARCHAR(30), active BOOLEAN DEFAULT TRUE);
